  "privWho1": "Cook 由［运营者的法定名称和邮寄地址］运营。如有隐私问题或请求，请联系［隐私邮箱地址］。这些信息必须在开放注册前补充完整。",
  "privWhat1": "当你创建账户时，我们会使用你的电子邮件、账户标识符、密码认证记录和验证状态来提供并保护你的账户。密码由认证服务提供商以安全哈希形式处理；Cook 不存储可读的密码。我们会保存你的厨房布局、所选语言、主题和计量单位，以便在所有设备上恢复你的设置。创建账户需要电子邮件和密码；不登录也可以浏览食谱。",
  "privWhat2": "处理账户和设置数据是提供你所请求的账户服务所必需的（GDPR 第 6 条第 1 款 (b) 项）。为保障安全和防止滥用，有限的记录可能会基于正当利益（第 6 条第 1 款 (f) 项）进行处理，以必要为限并经过权衡。验证邮件和密码重置邮件属于服务消息，而非营销。账户功能不会添加任何广告或分析。",
  "privStorage1": "Cook 使用 sessionStorage 在同一标签页的不同页面之间保留你的厨房、烹饪进度和选择。登录后，它还会保存你的认证会话。浏览器通常会在标签页会话结束时清除这些数据，但浏览器的会话恢复功能可能会保留它们。退出登录会清除 Cook 的标签页数据。关闭存储说明的状态只在该标签页中记住。Cook 自己的脚本不会设置 Cookie。你的托管或服务提供商可能有自己的安全处理，必须在上线前记录在案。",
  "privStorage2": "存储说明中的“确定”和关闭按钮只会关闭说明。它们不代表同意分析、广告或其他可选跟踪。今后任何非必要的存储都需要在开始前单独选择，并且拒绝和撤回同样简单。",
  "privOther1": "当前食谱列表的语音功能会根据你的 IP 地址向 country.is 查询大致所在国家，以选择语音识别语言。如果你使用麦克风识别，浏览器可能会将音频发送给其语音识别服务提供商。你也可以手动输入食材。在公开上线前，必须审查这些提供商、它们的政策以及这些功能的法律依据。",
  "privProviders1": "计划使用的账户服务提供商：Supabase（托管 PostgreSQL 和认证），使用所选的欧盟数据库区域。邮件服务提供商：［提供商］。网站托管：［提供商］。运营者必须确认实际的提供商、数据处理协议、次级处理者、日志存放位置以及向欧洲经济区以外的任何传输。欧盟数据库区域本身并不能排除跨境传输。如适用，请注明适用的充分性认定或合同保障措施，以及如何获取其副本。",
  "privRetention1": "账户设置会在你的账户有效期间保留。你可以通过上方的隐私联系方式请求删除。上线前，运营者必须明确删除请求的处理流程、未验证账户的过期时间，以及安全日志和备份的保留期限。已删除的数据可能会保留在访问受限的备份中，直至记录在案的备份保留期结束。",
  "privRights1": "根据适用条件，你可以请求访问、更正、删除、限制处理或数据可携，或反对基于正当利益的处理。请联系上方的运营者；请求通常会在一个月内得到答复，如依法延期会说明原因。你可以向监管机构投诉，包括匈牙利的 NAIH（naih.hu）。Cook 不会将账户设置用于产生法律效果或类似重大影响的自动化决策。",
