  "Flour browning": "面粉开始上色",
  "Wine in, reduce": "倒酒收汁",
  "Add the white wine and let it reduce by half, scraping the bottom of the pot.": "加入白葡萄酒，刮着锅底，收到剩一半。",
  "Reduced by half": "已收到一半",
  "Stock and herbs": "高汤和香草",
  "Add the stock (or water) and salt to taste. Add a pinch of nutmeg, the bay leaf and the thyme.": "加入高汤（或水），按口味加盐。加一小撮肉豆蔻、月桂叶和百里香。",
  "Simmer, stirring now and then.": "慢炖，不时搅拌。",
